UPDATE devices d SET first_seen_at = COALESCE(v.first_seen_at, d.first_seen_at), last_seen_at = v.last_seen_at, version_parts = COALESCE(v.version_parts::jsonb, d.version_parts), initial_version_parts = COALESCE(v.initial_version_parts::jsonb, d.initial_version_parts), updated_at = NOW() FROM (VALUES
(#{item.id}, #{item.firstSeenAt}, #{item.lastSeenAt}, #{item.versionPartsJson}, #{item.initialVersionPartsJson})
) AS v(id, first_seen_at, last_seen_at, version_parts, initial_version_parts) WHERE d.id = v.id
